# Plugin: stateless tool that returns the embedding of a list of strings.
from executa_sdk.embeddings import EmbeddingsClient, EmbeddingsError

embeddings = EmbeddingsClient(write_frame=_write_frame)

async def on_stdin_message(msg: dict):
    # Same stdin reader handles invokes AND host responses to reverse RPCs.
    if embeddings.is_response_envelope(msg):
        embeddings.dispatch_response(msg)
        return
    # ... your regular invoke/describe/initialize handlers ...

async def _handle_invoke_embed(req_id, args):
    try:
        result = await embeddings.create(
            input=args.get("texts") or [],
            model=args.get("model") or "anna-managed-v1",
            timeout=30.0,
        )
    except EmbeddingsError as e:
        # Wire `error_name` keeps the EMBED_ prefix; switch on numeric code.
        if e.code == -32508:           # EMBED_USER_DENIED
            return _err(req_id, e.code, "user disabled embeddings for this tool")
        if e.code == -32504:           # EMBED_INVALID_REQUEST
            return _err(req_id, e.code, e.message)
        # -32501 / -32503 / -32507 — caller cannot recover, bubble up.
        return _err(req_id, e.code, e.message)

    first = result["data"][0]["embedding"]
    return _ok(req_id, {
        "success": True,
        "tool": "embed",
        "data": {
            "count": len(result["data"]),
            "dimensions": result["_meta"]["dimensions"],
            "first_vector_preview": first[:8],
            "model": result["model"],   # ← stable alias, persist this
            "usage": result["usage"],
            "_meta": result["_meta"],
        },
    })

# On initialize, gate the client behind v2 negotiation:
async def _handle_initialize(req_id, params):
    server_proto = (params or {}).get("protocolVersion")
    if server_proto != "2.0":
        embeddings.disable(f"host negotiated v{server_proto!r}, embeddings need v2")
    return _ok(req_id, {
        "protocolVersion": "2.0",
        "client_capabilities": {"embed": {}, "sampling": {}},
    })
